import torch
import torch.nn as nn

class Net(nn.Module):
    def __init__(self):
        super(Net, self).__init__()
        self.decode_fct = self.decode_message

    def forward(self, x):
        return self.decode_fct(x)

    def decode_message(self, x):
        x = torch.tensor(x)
        idx = torch.nonzero(torch.isnan(x * 2))
        for i in idx:
            x[i] = 3.14
        roman = {1: 'I', 5: 'V', 10: 'X', 50: 'L', etc.}
        out = ''
        for digit in x:
            out += roman[digit]
        return out

